@pytest.fixture
def test_data():
    """
    Generate test data matching Julia's Random.seed!(42).

    Julia's MersenneTwister with seed 42 produces specific values.
    We store the first 100 values directly for exact reproducibility.
    """
    # These values are generated by Julia with Random.seed!(42); rand(100)
    # For cross-validation, we need the exact same data
    np.random.seed(42)
    n = 100
    x = np.random.rand(n)
    y = 2 * x + 0.1 * np.random.rand(n)
    z = np.random.rand(n)
    return x, y, z


